/**
 * Readable listing slugs ("titlu-citibil-<SKU>"), generated by lib/commerce/seo/titles.ts.
 *   npx tsx --env-file=.env.local scripts/commerce/apply-slugs.ts            (dry run: counts + sample, writes a backup-style CSV of old→new)
 *   npx tsx --env-file=.env.local scripts/commerce/apply-slugs.ts --apply
 * The API keeps resolving the OLD slug (by the SKU at the end) and answers with the new one, so old links/carts keep working.
 * listing.updatedAt is not changed. Idempotent: listings already on their generated slug are skipped.
 */
import fs from 'fs'
import os from 'os'
import path from 'path'
import { db } from '@repo/db'
import { loadSeoRows } from '../../lib/commerce/seo/data'
import { buildSeo } from '../../lib/commerce/seo/titles'

const CHUNK = 2000
async function main() {
  const apply = process.argv.includes('--apply')
  const bl = await db.businessLine.findUnique({ where: { slug: 'ecaroseria' }, select: { id: true } })
  if (!bl) throw new Error('business line not found')
  const rows = await loadSeoRows({ businessLineId: bl.id })
  const items = rows.map((r) => ({ id: r.listingId, sku: r.sku, old: r.currentSlug, next: buildSeo(r).slug })).filter((x) => x.old !== x.next)

  const dir = path.join(os.homedir(), 'data', 'ecaroseria-feed', 'reports'); fs.mkdirSync(dir, { recursive: true })
  const file = path.join(dir, `slugs-${apply ? 'aplicate' : 'previzualizare'}-${new Date().toISOString().replace(/[:.]/g, '-')}.csv`)
  fs.writeFileSync(file, 'listingId,sku,slug_vechi,slug_nou\n' + items.map((x) => [x.id, x.sku, x.old, x.next].join(',')).join('\n') + '\n')

  // safety: every new slug must end with its SKU, be URL-safe, and be unique (also against slugs that stay as they are)
  const bad = items.filter((x) => !x.next.endsWith(`-${x.sku}`) || !/^[a-z0-9-]{1,140}$/.test(x.next))
  const all = new Map<string, number>(); for (const r of rows) { const s = items.find((x) => x.id === r.listingId)?.next ?? r.currentSlug; all.set(s, (all.get(s) ?? 0) + 1) }
  const dup = [...all.values()].filter((n) => n > 1).length
  console.log(JSON.stringify({ mode: apply ? 'SCRIERE' : 'dry-run', listings: rows.length, toChange: items.length, invalid: bad.length, duplicates: dup, csv: file, sample: items.slice(0, 3).map((x) => `${x.old}  →  ${x.next}`) }, null, 1))
  if (bad.length || dup) throw new Error('slug validation failed; nothing written')
  if (!apply) return

  let written = 0
  for (let i = 0; i < items.length; i += CHUNK) {
    const part = items.slice(i, i + CHUNK)
    written += Number(await db.$executeRaw`
      UPDATE "CommerceListing" l SET slug = u.s
      FROM unnest(${part.map((x) => x.id)}::text[], ${part.map((x) => x.next)}::text[]) AS u(id, s)
      WHERE l.id = u.id AND l."businessLineId" = ${bl.id}`)
  }
  console.log(`slug-uri scrise: ${written}`)
}
main().then(() => process.exit(0)).catch((e) => { console.error(e instanceof Error ? e.message : e); process.exit(1) })
